/**
 * Generated by quail.
 *
 * Locale-switching smoke for https://www.spritecloud.com/. Iterates each detected
 * <link rel="alternate" hreflang> sibling; each becomes one test.
 *
 * Filter: `npx playwright test --grep @kind:i18n`
 */
import { test, expect } from '@playwright/test'
import { mobileNav, assertHeadingVisible, assertHtmlLang } from '../prims'

type Locale = { lang: string; url: string }

const LOCALES: Locale[] = [
]

test.describe.configure({ mode: 'parallel' })
test.describe('Spritecloud — i18n locales', () => {
  test('@kind:i18n @smoke <html lang> attribute is present', async ({ page }) => {
    await mobileNav(page, 'https://www.spritecloud.com/')
    await assertHtmlLang(page)
  })

  for (const locale of LOCALES) {
    test(`@kind:i18n @smoke ${locale.lang} variant renders`, async ({ page }) => {
      const response = await page.goto(locale.url)
      expect(response?.status(), `locale ${locale.lang} should respond`).toBeLessThan(400)
      await assertHtmlLang(page, locale.lang)
      await assertHeadingVisible(page)
    })
  }
})
